<script setup lang="ts">
import { ref,watch } from 'vue'
import type { ResearchAnalysis,Evidence } from '../types/copilot'
import EvidenceList from './AnalysisEvidence.vue'
const props=defineProps<{analysis:ResearchAnalysis;expanded?:boolean}>()
defineEmits<{expand:[]}>()
const detail=ref<{title:string;text:string;evidence:Evidence[]}|null>(null)
watch(()=>props.analysis.id,()=>detail.value=null)
</script>
<template><article v-if="analysis.result" class="analysis-result"><div class="analysis-result-heading"><span class="section-mini-label">AI 归纳 · {{analysis.state==='insufficient_data'?'资料范围有限':'基于提供的片段'}}</span><h3>{{analysis.result.title||'科研分析'}}</h3></div><p v-if="analysis.state==='insufficient_data'" class="analysis-scope" role="status">部分来源仅为元数据，不能据此确认论文实验或全文结论。</p><p class="analysis-summary">{{analysis.result.summary}}</p><details v-if="analysis.result.details" :open="expanded&&!analysis.result.comparison.length"><summary>详细解释</summary><p class="analysis-detail-text">{{analysis.result.details}}</p></details>
  <template v-if="analysis.result.comparison.length"><button v-if="!expanded" class="secondary-button full-width" @click="$emit('expand')">在研究空间展开对比表 ↗</button><div v-else class="comparison-table-scroll"><table class="comparison-table"><caption>论文对比表 · 点击单元格查看解释与证据</caption><thead><tr><th scope="col">维度</th><th v-for="s in analysis.sources" :key="s.id" scope="col">{{s.title}}</th></tr></thead><tbody><tr v-for="row in analysis.result.comparison" :key="row.dimension"><th scope="row">{{row.dimension}}</th><td v-for="cell in row.cells" :key="cell.paperId"><button :aria-label="`${row.dimension}：${analysis.sources.find(s=>s.id===cell.paperId)?.title}`" :aria-expanded="detail?.title===row.dimension+' · '+analysis.sources.find(s=>s.id===cell.paperId)?.title" @click="detail={title:row.dimension+' · '+analysis.sources.find(s=>s.id===cell.paperId)?.title,text:cell.text,evidence:cell.evidence}">{{cell.text}}</button></td></tr></tbody></table></div><section v-if="expanded&&detail" class="comparison-cell-detail" aria-live="polite"><h4>{{detail.title}}</h4><p>{{detail.text}}</p><EvidenceList :items="detail.evidence" :sources="analysis.sources"/><p v-if="!detail.evidence.length" class="settings-hint">未提供可定位原文证据。该内容为 AI 归纳或资料不足说明。</p><button class="text-button" @click="detail=null">收起解释</button></section></template>
  <EvidenceList :items="analysis.result.evidence" :sources="analysis.sources"/>
  <section v-for="group in [{title:'共同研究方向 · AI 归纳',items:analysis.result.commonalities},{title:'方法差异 · AI 归纳',items:analysis.result.differences},{title:'后续研究方向 · AI 推测，待验证',items:analysis.result.directions},{title:'继续探索建议',items:analysis.result.suggestions}]" :key="group.title" class="analysis-list"><template v-if="group.items.length"><h4>{{group.title}}</h4><ul><li v-for="s in group.items" :key="s">{{s}}</li></ul></template></section>
  <details class="analysis-source-list"><summary>来源与证据范围（{{analysis.sources.length}}）</summary><section v-for="s in analysis.sources" :key="s.id"><strong>{{s.title}}</strong><p>{{s.scope==='pdf_excerpt'?'用户明确提供的 PDF 解析片段，未保证覆盖全文':'提供或预置的元数据，未经全文核验'}}</p><a v-if="s.url" :href="s.url" target="_blank" rel="noopener noreferrer">原文来源 ↗</a><details v-for="e in s.excerpts" :key="e.id"><summary>{{e.page?'PDF 第 '+e.page+' 页':'元数据片段'}} · {{e.id}}</summary><blockquote>{{e.text}}</blockquote></details></section></details>
</article></template>
